package main

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net/http"
	"net/http/httptest"

	"github.com/gopernicus/gopernicus/pockets/authentication"
	authenticationhttp "github.com/gopernicus/gopernicus/pockets/authentication/inbound/http"
	"github.com/gopernicus/gopernicus/pockets/authorization"
	authorizationhttp "github.com/gopernicus/gopernicus/pockets/authorization/inbound/http"
	"github.com/gopernicus/gopernicus/pockets/authorization/logic/decisions"
	"github.com/gopernicus/gopernicus/pockets/authorization/logic/model"
	"github.com/gopernicus/gopernicus/pockets/authorization/logic/mutations"
	"github.com/gopernicus/gopernicus/pockets/authorization/logic/tuples"
	"github.com/gopernicus/gopernicus/pockets/authorization/stores/memory"
	"github.com/gopernicus/gopernicus/sdk"
)

func main() {
	ctx := context.Background()
	store := memory.New(memory.WithIntegrityPolicy(mutations.IntegrityPolicy{Rules: []mutations.IntegrityRule{{ResourceType: "project", Relation: "owner", MinSubjects: 1}}}))
	schema := decisions.Model{ResourceTypes: map[string]decisions.ResourceTypeDef{
		"platform": {Relations: map[string]decisions.RelationDef{"admin": {AllowedSubjects: []decisions.SubjectTypeRef{{Type: "user"}}}}, Permissions: map[string]decisions.Expression{"admin": decisions.Direct("admin")}},
		"document": {Permissions: map[string]decisions.Expression{"view": decisions.RoleIn("viewer")}},
	}}
	var logs bytes.Buffer
	logger := slog.New(slog.NewJSONHandler(&logs, &slog.HandlerOptions{Level: slog.LevelDebug}))
	components, err := authorization.New(authorization.Repositories{Tuples: store.Tuples(), Mutations: store.Mutations()}, authorization.WithModel(schema), authorization.WithLogger(logger))
	must(err)
	authorizer := components.Decisions
	administration := authentication.AdministrationConfig{
		UserAdminCheck: func(ctx context.Context, req authenticationhttp.UserAdminCheckRequest) error {
			result, err := authorizer.Check(ctx, model.CheckRequest{Principal: model.PrincipalFrom(req.Principal), Permission: "admin", Resource: model.Resource{Type: "platform", ID: "main"}})
			if err != nil {
				return err
			}
			if !result.Allowed {
				return sdk.ErrForbidden
			}
			return nil
		},
	}
	_ = authentication.WithAdministration(administration)
	req := authenticationhttp.UserAdminCheckRequest{Principal: sdk.Principal{Type: "user", ID: "alice"}}
	if err := administration.UserAdminCheck(ctx, req); !errors.Is(err, sdk.ErrForbidden) {
		panic(fmt.Sprintf("expected admin denial: %v", err))
	}
	_, err = components.Mutations.GrantRelationship(ctx, mutations.GrantRelationshipCommand{ResourceType: "platform", ResourceID: "main", Relation: "admin", Subject: tuples.SubjectRef{Type: "user", ID: "alice"}})
	must(err)
	must(administration.UserAdminCheck(ctx, req))
	guard := components.HTTP.Require(authorizationhttp.Can("view", authorizationhttp.Path("document", "documentID")), authorizationhttp.WithDeniedHandler(http.NotFoundHandler()))
	called := false
	handler := guard(http.HandlerFunc(func(http.ResponseWriter, *http.Request) { called = true }))
	request := httptest.NewRequest("GET", "/documents/d1", nil)
	request.SetPathValue("documentID", "d1")
	request = request.WithContext(sdk.WithPrincipal(request.Context(), req.Principal))
	result := httptest.NewRecorder()
	handler.ServeHTTP(result, request)
	if result.Code != 404 || called {
		panic(fmt.Sprintf("denial hook status=%d handler=%v", result.Code, called))
	}
	if bytes.Count(logs.Bytes(), []byte(`"msg":"authorization decision"`)) != 3 {
		panic("expected one DEBUG line for each of the three decisions")
	}
	_, err = mutations.NewService(nil)
	if !errors.Is(err, mutations.ErrMutationsNotConfigured) {
		panic("nil repository accepted")
	}
	readsOnly, err := authorization.New(authorization.Repositories{Tuples: store.Tuples()})
	must(err)
	if readsOnly.Mutations != nil {
		panic("missing repository exposed writer")
	}
	compiled, err := decisions.Compile(schema)
	must(err)
	writes, err := mutations.NewService(store.Mutations(), mutations.WithModel(compiled))
	must(err)
	_, err = writes.GrantRelationship(ctx, mutations.GrantRelationshipCommand{ResourceType: "project", ResourceID: "p1", Relation: "owner", Subject: tuples.SubjectRef{Type: "user", ID: "alice"}})
	must(err)
	_, err = writes.RevokeRelationship(ctx, mutations.RevokeRelationshipCommand{ResourceType: "project", ResourceID: "p1", Relation: "owner", Subject: tuples.SubjectRef{Type: "user", ID: "alice"}})
	if !errors.Is(err, sdk.ErrConflict) {
		panic("last owner was removed")
	}
	fmt.Println("PASS: documented admin check handles deny/allow; Require returns 404 without invoking protected handler; three decisions emit three DEBUG records; nil writer and atomic integrity behavior match docs")
}
func must(err error) {
	if err != nil {
		panic(err)
	}
}
